#ifndef HTTPRESPONSE_HPP
#define HTTPRESPONSE_HPP

#include <map>
#include <string>

/*
** HttpResponse - Programmer 3
** Holds status + headers + body and serializes them into raw HTTP.
** Content-Length and "Connection: close" are always generated by to_string(),
** so Server::handle_client_write() keeps working unchanged.
*/
class HttpResponse
{
public:
    HttpResponse();
    explicit HttpResponse(int status_code);

    void set_status(int code);
    int get_status() const;

    void set_header(const std::string &name, const std::string &value);
    void set_body(const std::string &body, const std::string &content_type);
    const std::string &get_body() const;

    // Full raw response (status line + headers + body).
    std::string to_string(const std::string &version) const;

    static std::string reason_phrase(int code);
    static std::string mime_type(const std::string &path);
    static std::string default_error_body(int code);
    static std::string html_escape(const std::string &text);

private:
    int _status;
    std::map<std::string, std::string> _headers;
    std::string _body;
};

#endif
